def edit_distance(source, target):
    """Calculates Levenshtein-like edit distance with sub cost 2."""
    m, n = len(source), len(target)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1): dp[i][0] = i
    for j in range(n + 1): dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if source[i - 1] == target[j - 1] else 2
            dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost)
    return dp[m][n]
def closest(word, dictionary):
    """Returns the word in dictionary with minimum edit distance."""
    return min(dictionary, key=lambda w: (edit_distance(word, w), dictionary.index(w)))
print(edit_distance("intention", "execution"))

